def _apply_ollama_buy_explanations(rows):
    out = [dict(r or {}) for r in list(rows or [])]
    if not out:
        return out
    now = time.time()
    for row in out:
        row.update(_default_buy_user_explanations(row))
        row["explanation_layer_source"] = "deterministic_fallback"
        row["ollama_explanation_used"] = False
    if not OLLAMA_INLINE_EXPLANATIONS_ENABLED:
        return out

    target = []
    for row in out:
        state = str(row.get("canonical_final_state") or "").strip().lower()
        if state in {"released_buy", "paper_ready", "watchlist"}:
            target.append(row)
    target = target[:OLLAMA_INLINE_MAX_BUY_ROWS]
    if not target:
        return out

    cache_bucket = _OLLAMA_INLINE_EXPLAIN_CACHE.setdefault("buy", {})
    missing = []
    for row in target:
        sig = _buy_row_explain_signature(row)
        cached = dict(cache_bucket.get(sig) or {})
        if cached and (now - _to_float(cached.get("ts"), 0.0)) <= OLLAMA_INLINE_EXPLAIN_TTL_SECONDS:
            data = dict(cached.get("data") or {})
            row.update({
                "user_buy_summary": _safe_text(data.get("buy"), 220) or row.get("user_buy_summary"),
                "user_caution_summary": _safe_text(data.get("caution"), 220) or row.get("user_caution_summary"),
                "user_invalidation_summary": _safe_text(data.get("invalidate"), 220) or row.get("user_invalidation_summary"),
                "explanation_layer_source": "ollama_cached",
                "ollama_explanation_used": True,
            })
            continue
        missing.append((sig, row))

    if not missing:
        return out

    model_status = _ollama_models_status_cached()
    if not bool(model_status.get("available")) or not str(model_status.get("selected_model") or "").strip():
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_run_utc"] = _now_utc_iso()
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_success"] = False
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = str(model_status.get("error") or "ollama_unavailable")
        return out

    prompt_rows = []
    for idx, (_sig, row) in enumerate(missing, start=1):
        prompt_rows.append(
            {
                "id": f"b{idx}",
                "symbol": str(row.get("symbol") or "").upper(),
                "state": str(row.get("canonical_final_state") or ""),
                "quality": round(_to_float(row.get("buy_quality_score"), _to_float(row.get("trade_quality_score"), 0.0)), 2),
                "confidence": round(_to_float(row.get("confidence"), _to_float(row.get("predicted_win_probability"), 0.0)), 2),
                "setup": str(row.get("setup_type") or ""),
                "confirmation": str(row.get("confirmation_state") or ""),
                "follow_through": str(row.get("follow_through_state") or ""),
                "blocker": str(
                    row.get("primary_hero_release_blocker")
                    or row.get("primary_promotion_blocker")
                    or row.get("primary_blocker")
                    or "none"
                ),
            }
        )
    prompt = (
        "Return strict JSON only. No markdown.\n"
        "For each item write simple plain-English text for a non-technical user.\n"
        "Keep each sentence <= 18 words.\n"
        "Schema: {\"items\":[{\"id\":\"b1\",\"buy\":\"...\",\"caution\":\"...\",\"invalidate\":\"...\"}]}\n"
        "Use only provided evidence. Be specific and concrete.\n"
        f"Input: {json.dumps({'items': prompt_rows}, ensure_ascii=True)}"
    )
    run = _ollama_run_prompt(prompt, timeout_seconds=OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS)
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_run_utc"] = _now_utc_iso()
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_success"] = bool(run.get("ok"))
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = str(run.get("error") or "")
    if not bool(run.get("ok")):
        return out
    parsed = _json_from_maybe_markdown(run.get("text"))
    items = list(parsed.get("items") or []) if isinstance(parsed, dict) else []
    by_id = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        key = str(item.get("id") or "").strip()
        if not key:
            continue
        by_id[key] = {
            "buy": _safe_text(item.get("buy"), 220),
            "caution": _safe_text(item.get("caution"), 220),
            "invalidate": _safe_text(item.get("invalidate"), 220),
        }
    for idx, (sig, row) in enumerate(missing, start=1):
        item = by_id.get(f"b{idx}") or {}
        if not item:
            continue
        row.update({
            "user_buy_summary": item.get("buy") or row.get("user_buy_summary"),
            "user_caution_summary": item.get("caution") or row.get("user_caution_summary"),
            "user_invalidation_summary": item.get("invalidate") or row.get("user_invalidation_summary"),
            "explanation_layer_source": "ollama_live",
            "ollama_explanation_used": True,
        })
        cache_bucket[sig] = {"ts": now, "data": dict(item)}
    return out


