@router.get("/api/tier1_probe_compare")
def tier1_probe_compare(symbols: str = "AAPL,MSFT,NVDA,TSLA,AMZN"):
    from core.guardian.guardian_secure_api import GuardianSecureAPI

    secure_api = GuardianSecureAPI()
    router_obj = getattr(secure_api, "_router", None)
    meta = get_ranking_snapshot_meta()
    cycle_map = {
        str(r.get("symbol", "")).upper(): r
        for r in list(meta.get("tier1_cycle_diagnostics", []))
        if isinstance(r, dict)
    }
    out = []
    providers = ["FMP", "FINNHUB", "POLYGON", "TWELVEDATA", "ALPACA"]
    for sym in [str(s).upper().strip() for s in symbols.split(",") if str(s).strip()]:
        direct = []
        if router_obj and hasattr(router_obj, "test_provider_quote"):
            for p in providers:
                try:
                    d = router_obj.test_provider_quote(provider=p, symbol=sym, asset_type="stock")
                    direct.append(
                        {
                            "provider": p,
                            "success_boolean": bool(d.get("success_boolean", False)),
                            "parsed_price": d.get("parsed_price"),
                            "parsed_prev_close": d.get("parsed_prev_close"),
                            "http_status": d.get("http_status"),
                            "error": d.get("error"),
                        }
                    )
                except Exception as e:
                    direct.append({"provider": p, "success_boolean": False, "error": str(e)[:180]})
        out.append(
            {
                "symbol": sym,
                "direct_probe": direct,
                "cycle_path": cycle_map.get(sym),
            }
        )
    return {"items": out}


