@router.get("/api/trust_status")
def trust_status():
    cached = _CACHE.get("trust_status", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= TRUST_TTL_SECONDS:
        payload = dict(cached["data"])
        payload["cached"] = True
        return payload

    provider_rows = provider_status()
    ranking_meta_payload = ranking_meta()
    learning = ADAPTIVE_LEARNING.learning_status()
    live = LIVE_SIGNAL_LOG.live_performance()
    gate = _gate_summary_from_items(LAST_RANKINGS.get("stocks", []))
