        def _buy_first_views(pack):
            hero_pool = list((pack.get("best_opportunities") or []))
            if not hero_pool:
                hero_pool = list((pack.get("final") or []))
            status_counts = {
                "live_deployable_now": 0,
                "paper_or_monitor_only": 0,
                "paper_ready": 0,
                "monitor_only": 0,
                "blocked": 0,
            }
            candidates = []
            for raw in hero_pool:
                if not isinstance(raw, dict):
                    continue
                row = dict(raw)
                if not _is_buy_direction(row):
                    continue
                action_tier_local = str(row.get("action_tier") or "").lower()
                trusted_local = bool(row.get("trusted_quote_for_buys", False))
                final_action_local = str(row.get("final_action") or "").lower()
                if action_tier_local in {"high_conviction_live_candidate", "live_candidate"} and trusted_local:
                    deployment_status = "live-ready"
                    action_model = "live_deployable_now"
                    status_counts["live_deployable_now"] += 1
                elif action_tier_local == "paper_ready" and trusted_local:
                    deployment_status = "paper-ready"
                    action_model = "paper_or_monitor_only"
                    status_counts["paper_or_monitor_only"] += 1
                    status_counts["paper_ready"] += 1
                elif action_tier_local in {"watchlist_only", "observe_only"} and trusted_local:
                    deployment_status = "monitor-only"
                    action_model = "paper_or_monitor_only"
                    status_counts["paper_or_monitor_only"] += 1
                    status_counts["monitor_only"] += 1
                else:
                    deployment_status = "blocked"
                    action_model = "paper_or_monitor_only"
                    status_counts["paper_or_monitor_only"] += 1
                    status_counts["blocked"] += 1
                row["top_pick_action_model"] = action_model
                row["candidate_vs_deployment_separation"] = {
                    "best_buy_candidate": True,
                    "live_deployable_now": bool(action_model == "live_deployable_now"),
                    "paper_or_monitor_only": bool(action_model == "paper_or_monitor_only"),
                }
                row["hero_deployment_status"] = deployment_status
                row["hero_card_deployment_label"] = deployment_status
                row["why_not_live_ready"] = (
                    "live_ready"
                    if deployment_status == "live-ready"
                    else str(row.get("primary_hero_release_blocker") or row.get("primary_promotion_blocker") or row.get("primary_blocker") or "paper_or_monitor_posture")
                )
                row["what_would_upgrade_this"] = str(
                    row.get("what_would_promote_this_to_hero")
                    or row.get("what_would_promote_this_to_buy")
                    or "improve_runtime_data_and_confirmation"
                )
                row["buy_first_action_engine"] = {
                    "best_buy_candidate": True,
                    "live_deployable_now": bool(action_model == "live_deployable_now"),
                    "paper_or_monitor_only": bool(action_model == "paper_or_monitor_only"),
                    "hero_deployment_status": deployment_status,
                    "actionability_quality_score": round(
                        (
                            _to_float(row.get("final_action_score"), _to_float(row.get("trade_quality_score"), 0.0)) * 0.6
                            + _to_float(row.get("promotion_readiness_score"), _to_float(row.get("live_data_quality_score"), 0.0)) * 0.4
                        ),
                        2,
                    ),
                }
                candidates.append(row)
            candidates = sorted(
                candidates,
                key=lambda x: (
                    0 if str((x or {}).get("hero_deployment_status") or "") == "live-ready" else 1,
                    -_to_float((x or {}).get("buy_first_action_engine", {}).get("actionability_quality_score"), 0.0),
                    -_to_float((x or {}).get("final_action_score"), _to_float((x or {}).get("trade_quality_score"), 0.0)),
                ),
            )
            quality_score = round(
                sum(_to_float((r or {}).get("buy_first_action_engine", {}).get("actionability_quality_score"), 0.0) for r in candidates)
                / max(1, len(candidates)),
                2,
            )
            return {
                "hero_candidates": candidates[:6],
                "hero_overflow": candidates[6:14],
                "status_counts": status_counts,
                "top_buy_candidate_count": int(len(candidates)),
                "best_buy_candidate_quality_score": quality_score,
            }
        stocks_buy_first = _buy_first_views(stock_pack)
