        false_negative_total = int(_to_float(stocks_fn.get("a_b_blocked_but_would_have_worked_count"), 0.0) + _to_float(crypto_fn.get("a_b_blocked_but_would_have_worked_count"), 0.0))
        false_positive_total = int(_to_float(stocks_fp.get("promoted_a_b_that_failed_fast_count"), 0.0) + _to_float(crypto_fp.get("promoted_a_b_that_failed_fast_count"), 0.0))
