def _provider_efficiency_architecture_status(meta=None):
    meta_local = dict(meta or get_ranking_snapshot_meta() or {})
    ws = ALPACA_WS_MONITOR.status()
    try:
        open_positions_count = int(len(POSITION_TRACKER.get_open_positions() or []))
    except Exception:
        open_positions_count = 0
    fmp_mode = str(meta_local.get("fmp_operating_mode") or os.getenv("ASTRA_FMP_MODE", "conserve")).strip().lower() or "conserve"
    fmp_ws_enabled = str(os.getenv("ASTRA_FMP_WS_ENABLED", "0")).strip().lower() in {"1", "true", "yes", "on"}
    ws_active = bool(ws.get("running", False)) or bool(fmp_ws_enabled)
    provider_by_job = dict(meta_local.get("provider_job_architecture") or {})
    provider_market_split = dict(meta_local.get("provider_market_split") or {})
    websocket_layers = dict(meta_local.get("websocket_live_learning_layers") or {})
    ws_priority = (ws.get("priority_classes") or {})
    open_positions_priority = ws_priority.get("open_positions", 0)
    if isinstance(open_positions_priority, (list, tuple, set)):
        open_positions_priority_count = len(open_positions_priority)
    elif isinstance(open_positions_priority, dict):
        open_positions_priority_count = len(open_positions_priority.keys())
    else:
        open_positions_priority_count = int(_to_float(open_positions_priority, 0.0))
    return {
        "fmp_mode": fmp_mode,
        "fmp_conserve_mode_active": bool(fmp_mode == "conserve"),
        "fmp_efficient_mode_ready": True,
        "fmp_websocket_enabled": bool(fmp_ws_enabled),
        "websocket_live_learning_active": bool(ws_active),
        "broad_discovery_active_reduced": bool(meta_local.get("broad_discovery_reduced_in_conserve_mode", False)),
        "shortlist_live_watch_active": bool(int(ws.get("desired_symbol_count", 0) or 0) > 0),
        "held_position_live_watch_active": bool(open_positions_count > 0 and open_positions_priority_count > 0),
        "stored_data_learning_active": bool(meta_local.get("stored_data_learning_active", True)),
        "provider_job_routing_active": bool(meta_local.get("provider_job_routing_active", True)),
        "provider_by_job_summary": provider_by_job,
        "provider_market_split": provider_market_split,
        "websocket_live_learning_layers": websocket_layers,
        "alpaca_ws_state": {
            "enabled": bool(ws.get("enabled", False)),
            "running": bool(ws.get("running", False)),
            "active_symbol_count": int(ws.get("active_symbol_count", 0) or 0),
            "desired_symbol_count": int(ws.get("desired_symbol_count", 0) or 0),
        },
        "open_positions_count": int(open_positions_count),
        "high_value_scan_window_active_et": bool(meta_local.get("high_value_scan_window_active_et", False)),
    }


