def _default_learning_weights_payload(message="Learning weights unavailable."):
    return {
        "generated_at": _now_utc_iso(),
        "last_updated_utc": _now_utc_iso(),
        "persona_weights": {},
        "signal_weights": {
            "signal_tag_weights": {},
            "signal_combo_weights": {},
        },
        "regime_weights": {},
        "buy_mode_performance": {},
        "top_winning_signals": [],
        "top_losing_signals": [],
        "signal_win_rates": [],
        "insufficient_data": True,
        "message": str(message or "Learning weights unavailable."),
    }


def _build_learning_weights_payload(insights_payload):
    payload = _default_learning_weights_payload()
    src = insights_payload if isinstance(insights_payload, dict) else {}
    adaptive = src.get("adaptive_weights", {}) if isinstance(src.get("adaptive_weights"), dict) else {}
    signal_perf = (
        (src.get("segments", {}) or {}).get("by_signal_tag", {})
        if isinstance(src.get("segments"), dict)
        else {}
    )
    if not isinstance(signal_perf, dict):
        signal_perf = {}
    signal_rows = []
    for tag, stats in signal_perf.items():
        st = stats if isinstance(stats, dict) else {}
        signal_rows.append(
            {
                "signal_tag": str(tag),
                "trade_count": int(_to_float(st.get("trade_count"), 0)),
                "win_rate": round(_to_float(st.get("win_rate"), 0.0), 2),
                "avg_return": round(_to_float(st.get("avg_return"), 0.0), 4),
                "avg_friction_return": round(_to_float(st.get("avg_friction_return"), 0.0), 4),
            }
        )
    signal_rows.sort(
        key=lambda r: (
            -float(r.get("avg_friction_return", 0.0)),
            -float(r.get("win_rate", 0.0)),
            -int(r.get("trade_count", 0)),
            str(r.get("signal_tag", "")),
        )
    )
    payload["generated_at"] = src.get("generated_at") or _now_utc_iso()
    payload["last_updated_utc"] = _now_utc_iso()
    payload["persona_weights"] = adaptive.get("persona_weights", {}) if isinstance(adaptive.get("persona_weights"), dict) else {}
    payload["signal_weights"] = {
        "signal_tag_weights": adaptive.get("signal_tag_weights", {}) if isinstance(adaptive.get("signal_tag_weights"), dict) else {},
        "signal_combo_weights": adaptive.get("signal_combo_weights", {}) if isinstance(adaptive.get("signal_combo_weights"), dict) else {},
    }
    payload["regime_weights"] = adaptive.get("regime_weights", {}) if isinstance(adaptive.get("regime_weights"), dict) else {}
    payload["buy_mode_performance"] = (
        (src.get("segments", {}) or {}).get("by_buy_mode", {})
        if isinstance(src.get("segments"), dict)
        else {}
    )
    payload["top_winning_signals"] = signal_rows[:10]
    payload["top_losing_signals"] = sorted(
        signal_rows,
        key=lambda r: (
            float(r.get("avg_friction_return", 0.0)),
            float(r.get("win_rate", 0.0)),
            -int(r.get("trade_count", 0)),
            str(r.get("signal_tag", "")),
        ),
    )[:10]
    payload["signal_win_rates"] = [
        {
            "signal_tag": str(r.get("signal_tag", "")),
            "win_rate": round(_to_float(r.get("win_rate"), 0.0), 2),
            "trade_count": int(_to_float(r.get("trade_count"), 0)),
        }
        for r in signal_rows
    ][:25]
    payload["insufficient_data"] = bool(src.get("insufficient_data", True))
    payload["message"] = (
        "Insufficient signal history for stable weight diagnostics."
        if payload["insufficient_data"]
        else "Adaptive learning weight diagnostics are active."
    )
    return payload


def _normalize_learning_insights_payload(payload):
    base = _default_learning_insights_payload()
    if not isinstance(payload, dict):
        payload = {}
    out = json.loads(json.dumps(base))
    out.update({k: v for k, v in payload.items() if k not in {"totals", "segments"}})
    totals = payload.get("totals") if isinstance(payload.get("totals"), dict) else {}
    out["totals"].update({k: v for k, v in totals.items() if k in out["totals"]})
    segments = payload.get("segments") if isinstance(payload.get("segments"), dict) else {}
    out["segments"].update({k: v for k, v in segments.items() if k in out["segments"]})
    for group in ("combined", "live_paper", "replay_paper", "hard_buy", "soft_buy"):
        candidate = totals.get(group) if isinstance(totals.get(group), dict) else {}
        current = out["totals"].get(group, {})
        if isinstance(current, dict):
            current.update({k: v for k, v in candidate.items() if k in current})
            out["totals"][group] = current
    if "hard_vs_soft_delta_avg_return" in totals:
        out["totals"]["hard_vs_soft_delta_avg_return"] = _to_float(totals.get("hard_vs_soft_delta_avg_return"), 0.0)
    if "hard_vs_soft_delta_winsorized_avg_return" in totals:
        out["totals"]["hard_vs_soft_delta_winsorized_avg_return"] = _to_float(
            totals.get("hard_vs_soft_delta_winsorized_avg_return"), 0.0
        )
    if isinstance(totals.get("source_contribution"), dict):
        sc = totals.get("source_contribution") or {}
        out["totals"]["source_contribution"] = {
            "live_paper_share_percent": _to_float(sc.get("live_paper_share_percent"), 0.0),
            "replay_paper_share_percent": _to_float(sc.get("replay_paper_share_percent"), 0.0),
        }
    tsc = payload.get("top_signals_by_cap_category")
    if isinstance(tsc, dict):
        for cap in ("large", "mid", "small"):
            if isinstance(tsc.get(cap), list):
                out["top_signals_by_cap_category"][cap] = tsc.get(cap)
    if not isinstance(out.get("learning_timeline"), list):
        out["learning_timeline"] = []
    if not isinstance(out.get("funnel_weight_hints"), dict):
        out["funnel_weight_hints"] = {}
