def _premium_backfill_symbol_universe(limit=200):
    symbols = []
    try:
        ranked = _get_cached_rankings("stocks") or []
        symbols.extend([str((r or {}).get("symbol") or "").upper() for r in ranked[: max(1, int(limit))]])
    except Exception:
        pass
    try:
        with sqlite3.connect(DB_PATH) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT DISTINCT symbol
                FROM paper_positions
                WHERE COALESCE(quantity, 0) > 0
                ORDER BY symbol
                LIMIT 60
                """
            ).fetchall()
        symbols.extend([str((r["symbol"] if r else "") or "").upper() for r in rows])
    except Exception:
        pass
    symbols.extend(FALLBACK_STOCK_SYMBOLS)
    dedup = []
    seen = set()
    for sym in symbols:
        s = str(sym or "").upper().strip()
        if not s or s in seen:
            continue
        if not s.isalpha() and "." not in s:
            continue
        seen.add(s)
        dedup.append(s)
        if len(dedup) >= int(limit):
            break
    return dedup


def _run_premium_backfill_step_if_due(force=False):
    trainer = _ensure_paper_replay_trainer()
    ds = getattr(trainer, "historical_dataset", None)
    if ds is None or not hasattr(ds, "run_premium_backfill_step"):
        return {"ok": False, "reason": "premium_backfill_unavailable"}
    now = time.time()
    if bool(_PREMIUM_BACKFILL_RUNTIME.get("in_progress", False)):
        return {"ok": True, "skipped": True, "reason": "in_progress"}
    if not force and (now - float(_PREMIUM_BACKFILL_RUNTIME.get("last_step_ts", 0.0))) < PREMIUM_BACKFILL_STEP_COOLDOWN_SECONDS:
        return {"ok": True, "skipped": True, "reason": "cooldown"}

    symbols = _premium_backfill_symbol_universe(limit=200)

    def _runner():
        try:
            step = ds.run_premium_backfill_step(symbols=symbols, max_symbols=24 if force else 12)
            _PREMIUM_BACKFILL_RUNTIME["last_status"] = dict(step or {})
            _PREMIUM_BACKFILL_RUNTIME["last_error"] = ""
        except Exception as e:
            _PREMIUM_BACKFILL_RUNTIME["last_error"] = str(e)[:280]
            _PREMIUM_BACKFILL_RUNTIME["last_status"] = {"ok": False, "reason": f"step_error:{str(e)[:120]}"}
        finally:
            _PREMIUM_BACKFILL_RUNTIME["last_step_ts"] = time.time()
            _PREMIUM_BACKFILL_RUNTIME["in_progress"] = False

    _PREMIUM_BACKFILL_RUNTIME["in_progress"] = True
    t = threading.Thread(target=_runner, daemon=True)
    t.start()
    return {"ok": True, "scheduled": True, "reason": "started"}


def _premium_learning_status_payload():
    trainer = _ensure_paper_replay_trainer()
    ds = getattr(trainer, "historical_dataset", None)
    base = {
        "status": "unavailable",
        "premium_mode": str(os.getenv("ASTRA_PREMIUM_MODE", "1")).strip().lower() in {"1", "true", "yes", "on"},
        "step_cooldown_seconds": int(PREMIUM_BACKFILL_STEP_COOLDOWN_SECONDS),
        "last_step_utc": "",
        "last_step_error": str(_PREMIUM_BACKFILL_RUNTIME.get("last_error") or ""),
        "step_in_progress": bool(_PREMIUM_BACKFILL_RUNTIME.get("in_progress", False)),
        "backfill_in_progress": False,
        "scan_windows": [w.strip() for w in str(os.getenv("ASTRA_PREMIUM_SCAN_WINDOWS", "premarket,midday,near_close")).split(",") if w.strip()],
        "broad_scan_plan": {
            "scan_universe_target": 200,
            "high_value_windows": ["premarket", "midday", "near_close"],
            "focused_live_monitoring": ["open_positions", "near_entry", "released_heroes"],
        },
    }
    if ds is None:
        return base
    try:
        depth = ds.depth_summary() if hasattr(ds, "depth_summary") else {}
    except Exception:
        depth = {}
    try:
        premium = ds.premium_backfill_status() if hasattr(ds, "premium_backfill_status") else {}
    except Exception:
        premium = {}
    status = dict(base)
    status["status"] = "active"
    status["historical_depth"] = depth
    status["premium_backfill_status"] = premium
    status["last_step_utc"] = str((premium or {}).get("last_step_utc") or "")
    status["backfill_in_progress"] = bool(
        _PREMIUM_BACKFILL_RUNTIME.get("in_progress", False)
        or str((premium or {}).get("current_stage") or "") not in {"", "integration_ready"}
    )
    status["provider_distribution"] = dict((depth or {}).get("provider_distribution") or {})
    status["fmp_history_share_pct"] = round(
        (
            (_to_float(((depth or {}).get("provider_distribution") or {}).get("FMP_HIST"), 0.0)
             / max(1.0, _to_float((depth or {}).get("total_bars"), 0.0)))
            * 100.0
        ),
        2,
    )
    return status


@router.get("/api/learning_insights")
def learning_insights():
    li_t0 = time.perf_counter()
    def _learning_budget_exceeded(limit_seconds=8.0):
        return (time.perf_counter() - li_t0) >= float(limit_seconds)
    _schedule_runtime_warmup()
    try:
        payload = _get_enriched_learning_insights_cached()
    except Exception as e:
        last_good = _load_learning_insights_last_good()
        if isinstance(last_good, dict) and _learning_payload_is_nonzero(last_good):
            payload = _decorate_learning_payload_resilience(
                last_good,
                source="last_known_good_endpoint_exception",
                stale=True,
                degraded_reason=str(e)[:120],
                false_empty_prevented=True,
            )
            payload["stale_cache"] = True
            payload["stale_cache_reason"] = "endpoint_exception_last_known_good"
            payload["degraded_db_access"] = True
            payload["degraded_reason"] = str(e)[:120]
        else:
            payload = _default_learning_insights_payload(
                message=f"Learning insights unavailable: {str(e)[:120]}"
            )
            payload = _decorate_learning_payload_resilience(
                payload,
                source="default_endpoint_exception",
                stale=True,
                degraded_reason=str(e)[:120],
                false_empty_prevented=False,
            )
    payload = _ensure_learning_payload_handoff(payload, reason_hint="learning_insights_endpoint_pre_eval")

    def _attach_current_engine_eval_fields(target_payload):
        try:
            eval_payload_local = _get_current_engine_outcome_eval_fast()
        except Exception:
            eval_payload_local = _default_current_engine_outcome_eval_payload()
            eval_payload_local["cohort_mode"] = "unavailable"
            eval_payload_local["cohort_quality_note"] = "current_engine_outcome_evaluation_unavailable"
        target_payload["current_engine_outcome_evaluation"] = dict(eval_payload_local or {})
        for key in (
            "released_hero_win_rate",
            "paper_ready_win_rate",
            "blocked_watchlist_win_rate",
            "released_vs_paper_ready_win_rate_delta",
            "released_vs_blocked_win_rate_delta",
            "released_hero_expectancy",
            "paper_ready_expectancy",
            "blocked_watchlist_expectancy",
            "released_high_confidence_win_rate",
            "released_medium_confidence_win_rate",
            "released_fast_loss_rate",
            "current_engine_exit_timing_score",
            "current_engine_profit_protection_score",
            "current_engine_late_exit_rate",
            "current_engine_premature_exit_rate",
            "current_engine_sell_quality_note",
            "current_engine_sell_side_sample_size",
            "cohort_sample_sizes",
            "cohort_window_days",
            "cohort_mode",
            "cohort_quality_note",
            "confidence_comparison_reliable",
            "post_change_cohort_mode",
            "post_change_cohort_start_utc",
            "post_change_sample_sizes",
            "post_change_released_win_rate",
            "post_change_paper_ready_win_rate",
            "post_change_blocked_watchlist_win_rate",
            "post_change_released_expectancy",
            "post_change_paper_ready_expectancy",
            "post_change_blocked_watchlist_expectancy",
            "post_change_released_fast_loss_rate",
            "post_change_high_confidence_win_rate",
            "post_change_medium_confidence_win_rate",
            "post_change_confidence_comparison_reliable",
            "post_change_cohort_quality_note",
            "post_change_evidence_ready",
            "post_change_confidence_ready",
            "post_change_released_vs_paper_ready_expectancy_delta",
            "post_change_released_vs_blocked_expectancy_delta",
            "post_change_exit_timing_score",
            "post_change_profit_protection_score",
            "post_change_late_exit_rate",
            "post_change_premature_exit_rate",
            "post_change_sell_quality_note",
            "post_change_sell_side_sample_size",
            "post_change_min_sample_requirements",
        ):
            if key in eval_payload_local:
                target_payload[key] = eval_payload_local.get(key)

        # Keep A/B cohort counters populated from live runtime snapshot cache
        # when available, even on learning_insights fast-path responses.
        top_payload_local = _latest_top_buys_runtime_snapshot()
        cps_local = {}
        if isinstance(top_payload_local, dict):
            cps_local = dict(top_payload_local.get("candidate_promotion_summary") or {})
        ab_ranked_local = int(
            _to_float(
                eval_payload_local.get("a_b_ranked_count"),
                _to_float(cps_local.get("a_b_ranked_count"), 0.0),
            )
        )
        ab_promoted_local = int(
            _to_float(
                eval_payload_local.get("a_b_promoted_to_strong_buy_count"),
                _to_float(cps_local.get("a_b_promoted_to_strong_buy_count"), 0.0),
            )
        )
        ab_blocked_local = int(
            _to_float(
                eval_payload_local.get("a_b_blocked_count"),
                _to_float(cps_local.get("a_b_blocked_count"), max(0.0, ab_ranked_local - ab_promoted_local)),
            )
        )
        if ab_ranked_local > 0 or ab_promoted_local > 0 or ab_blocked_local > 0:
            target_payload["a_b_ranked_count"] = ab_ranked_local
            target_payload["a_b_promoted_to_strong_buy_count"] = ab_promoted_local
            target_payload["a_b_blocked_count"] = ab_blocked_local
            ce_local = dict(target_payload.get("current_engine_outcome_evaluation") or {})
            ce_local.setdefault("a_b_ranked_count", ab_ranked_local)
            ce_local.setdefault("a_b_promoted_to_strong_buy_count", ab_promoted_local)
            ce_local.setdefault("a_b_blocked_count", ab_blocked_local)
            target_payload["current_engine_outcome_evaluation"] = ce_local

        return eval_payload_local

    def _attach_current_cohort_submetrics_fast(target_payload, eval_payload_local):
        out_local = dict(target_payload or {})
        try:
            out_local = _apply_learning_tab_consistency(out_local, eval_payload_local)
        except Exception:
            pass

        current_mode_local = str((eval_payload_local or {}).get("cohort_mode") or "unavailable")
        post_mode_local = str((eval_payload_local or {}).get("post_change_cohort_mode") or "unavailable")
        current_sizes_local = dict((eval_payload_local or {}).get("cohort_sample_sizes") or {})
        post_sizes_local = dict((eval_payload_local or {}).get("post_change_sample_sizes") or {})

        out_local["current_engine_status"] = {
            "status": "active" if current_mode_local not in {"", "unavailable", "insufficient_data"} else "degraded",
            "cohort_mode": current_mode_local,
            "sample_sizes": current_sizes_local,
            "confidence_comparison_reliable": bool((eval_payload_local or {}).get("confidence_comparison_reliable", False)),
        }
        out_local["post_change_status"] = {
            "status": "evidence_ready" if bool((eval_payload_local or {}).get("post_change_evidence_ready")) else "sample_limited",
            "cohort_mode": post_mode_local,
            "sample_sizes": post_sizes_local,
            "evidence_ready": bool((eval_payload_local or {}).get("post_change_evidence_ready")),
            "confidence_ready": bool((eval_payload_local or {}).get("post_change_confidence_ready")),
        }

        perf_local = _performance_optimization_snapshot()
        out_local["runtime_performance_summary"] = {
            "steady_state_top_buys_ms": round(_to_float((((perf_local.get("hot_path_timings_ms") or {}).get("top_buys_total") or {}).get("last_ms")), 0.0), 3),
            "steady_state_learning_ms": round(_to_float((((perf_local.get("hot_path_timings_ms") or {}).get("learning_insights_total") or {}).get("last_ms")), 0.0), 3),
            "cold_top_buys_rows_fetch_ms": round(_to_float((((perf_local.get("hot_path_timings_ms") or {}).get("top_buys_rows_fetch") or {}).get("max_ms")), 0.0), 3),
        }

        actionability_local = dict(out_local.get("actionability_quality_suite") or {})
        if isinstance(actionability_local, dict):
            if "a_b_ranked" in actionability_local:
                out_local["a_b_ranked_count"] = int(_to_float(actionability_local.get("a_b_ranked"), 0.0))
            if "a_b_promoted" in actionability_local:
                out_local["a_b_promoted_to_strong_buy_count"] = int(_to_float(actionability_local.get("a_b_promoted"), 0.0))
            if "a_b_blocked" in actionability_local:
                out_local["a_b_blocked_count"] = int(_to_float(actionability_local.get("a_b_blocked"), 0.0))

        totals_local = dict((out_local.get("totals") or {}).get("combined") or {})
        trade_count_local = int(_to_float(totals_local.get("trade_count"), 0.0))
        win_rate_local = _to_float(totals_local.get("win_rate"), 0.0)
        if trade_count_local > 0:
            good_entries_local = int(round((trade_count_local * max(0.0, min(100.0, win_rate_local))) / 100.0))
            bad_entries_local = int(max(0, trade_count_local - good_entries_local))
            out_local["good_entries"] = good_entries_local
            out_local["bad_entries"] = bad_entries_local
            out_local["entry_edge"] = round((good_entries_local - bad_entries_local) / max(1.0, float(trade_count_local)), 4)

        entry_exec_local = dict(out_local.get("entry_execution_quality") or {})
        follow_local = dict(out_local.get("followthrough_quality") or {})
        out_local["observation_proof_metrics"] = {
            "entry_quality_score": round(_to_float(entry_exec_local.get("entry_quality_score"), 0.0), 2),
            "follow_through_quality_score": round(_to_float(follow_local.get("follow_through_entry_score"), 0.0), 2),
            "weak_follow_through_rate_estimate": round(_to_float(follow_local.get("weak_follow_through_score"), 0.0), 2),
            "immediate_failure_rate_estimate": round(_to_float((eval_payload_local or {}).get("released_fast_loss_rate"), 0.0), 2),
            "current_engine_sample_sizes": current_sizes_local,
        }

        return out_local

    fast_mode = str(os.getenv("ASTRA_LEARNING_INSIGHTS_LIGHT_MODE", "1")).strip().lower() in {"1", "true", "yes", "on"}
    if fast_mode:
        eval_payload = _attach_current_engine_eval_fields(payload)
        payload = _attach_current_cohort_submetrics_fast(payload, eval_payload)
        payload["learning_insights_fast_path"] = True
        payload["learning_insights_fast_path_reason"] = "light_mode_enabled"
        payload["last_updated_utc"] = _now_utc_iso()
        return payload
    if _learning_budget_exceeded(4.0):
        eval_payload = _attach_current_engine_eval_fields(payload)
        payload = _attach_current_cohort_submetrics_fast(payload, eval_payload)
        payload["learning_insights_fast_path"] = True
        payload["learning_insights_fast_path_reason"] = "budget_guard_pre_eval"
        payload["last_updated_utc"] = _now_utc_iso()
        return payload
    eval_payload = _attach_current_engine_eval_fields(payload)
    try:
        high_conf_wr_eval = _to_float(payload.get("released_high_confidence_win_rate"), None)
        med_conf_wr_eval = _to_float(payload.get("released_medium_confidence_win_rate"), None)
        released_exp_eval = _to_float(payload.get("released_hero_expectancy"), None)
        paper_exp_eval = _to_float(payload.get("paper_ready_expectancy"), None)
        blocked_exp_eval = _to_float(payload.get("blocked_watchlist_expectancy"), None)
        confidence_compare_reliable = bool(payload.get("confidence_comparison_reliable", False))
        confidence_gap_eval = None
        if high_conf_wr_eval is not None and med_conf_wr_eval is not None:
            confidence_gap_eval = high_conf_wr_eval - med_conf_wr_eval
        expectancy_edge_score = 0.0
        if released_exp_eval is not None and paper_exp_eval is not None and blocked_exp_eval is not None:
            expectancy_edge_score = max(
                0.0,
                min(
                    100.0,
                    50.0
                    + max(-25.0, min(25.0, (released_exp_eval - paper_exp_eval) * 60.0))
                    + max(-25.0, min(25.0, (released_exp_eval - blocked_exp_eval) * 60.0)),
                ),
            )
        confidence_calibration = dict(payload.get("confidence_calibration") or {})
        overconfidence_detected = bool(confidence_calibration.get("overconfidence_detected", False))
        confidence_recalibration_engine = dict(payload.get("confidence_recalibration_engine") or {})
        confidence_truthfulness_engine = dict(payload.get("confidence_truthfulness_engine") or {})
        if high_conf_wr_eval is not None:
            confidence_recalibration_engine["high_confidence_predictiveness_score"] = round(
                max(0.0, min(100.0, high_conf_wr_eval * 2.5)),
                2,
            )
        if confidence_gap_eval is not None:
            bucket_separation_score = round(
                max(0.0, min(100.0, 50.0 + confidence_gap_eval * 4.0)),
                2,
            )
            confidence_recalibration_engine["confidence_bucket_separation_score"] = bucket_separation_score
            confidence_recalibration_engine["confidence_understatement_score"] = round(
                max(0.0, min(100.0, max(0.0, confidence_gap_eval) * 1.5)),
                2,
            )
        elite_confidence_quality_score = confidence_recalibration_engine.get("elite_confidence_quality_score")
        if high_conf_wr_eval is not None:
            confidence_alignment_local = _to_float(
                (payload.get("outcome_first_decision_engine") or {}).get("confidence_alignment_score"),
                _to_float(confidence_calibration.get("confidence_calibration_score"), 50.0),
            )
            elite_confidence_quality_score = round(
                max(
                    0.0,
                    min(
                        100.0,
                        (high_conf_wr_eval * 1.75)
                        + (max(0.0, confidence_gap_eval or 0.0) * 2.0)
                        + (confidence_alignment_local * 0.30)
                        + (expectancy_edge_score * 0.20),
                    ),
                ),
                2,
            )
            confidence_recalibration_engine["elite_confidence_quality_score"] = elite_confidence_quality_score
        confidence_truthfulness_score = confidence_truthfulness_engine.get("confidence_truthfulness_score")
        if high_conf_wr_eval is not None:
            false_positive_rate = round(
                max(
                    0.0,
                    min(
                        100.0,
                        100.0
                        - max(0.0, min(100.0, high_conf_wr_eval * 2.2))
                        - max(0.0, min(20.0, max(0.0, confidence_gap_eval or 0.0) * 1.8)),
                    ),
                ),
                2,
            )
            confidence_truthfulness_engine["high_confidence_false_positive_rate"] = false_positive_rate
            confidence_truthfulness_engine["high_confidence_true_positive_rate"] = round(
                max(0.0, min(100.0, high_conf_wr_eval * 2.5)),
                2,
            )
            confidence_truthfulness_engine["confidence_predictiveness_score"] = round(
                max(
                    0.0,
                    min(
                        100.0,
                        50.0
                        + max(-20.0, min(20.0, (confidence_gap_eval or 0.0) * 3.5))
                        + max(-15.0, min(15.0, (expectancy_edge_score - 50.0) * 0.5)),
                    ),
                ),
                2,
            )
            confidence_truthfulness_engine["high_confidence_release_quality_score"] = round(
                max(0.0, min(100.0, _to_float(elite_confidence_quality_score, 0.0))),
                2,
            )
            confidence_truthfulness_score = round(
                max(
                    0.0,
                    min(
                        100.0,
                        (confidence_truthfulness_engine["high_confidence_true_positive_rate"] * 0.35)
                        + ((100.0 - confidence_truthfulness_engine["high_confidence_false_positive_rate"]) * 0.20)
                        + (confidence_truthfulness_engine["confidence_predictiveness_score"] * 0.20)
                        + (_to_float(confidence_calibration.get("confidence_calibration_score"), 0.0) * 0.25),
                    ),
                ),
                2,
            )
            confidence_truthfulness_engine["confidence_truthfulness_score"] = confidence_truthfulness_score
            confidence_truthfulness_engine["confidence_repair_score"] = round(
                max(
                    0.0,
                    min(
                        100.0,
                        (confidence_truthfulness_score * 0.6)
                        + (_to_float(confidence_truthfulness_engine.get("confidence_predictiveness_score"), 0.0) * 0.4),
                    ),
                ),
                2,
            )
        confidence_truthfulness_engine["overconfidence_detected"] = overconfidence_detected
        confidence_truthfulness_engine["confidence_comparison_reliable"] = confidence_compare_reliable
        payload["confidence_recalibration_engine"] = confidence_recalibration_engine
        payload["confidence_truthfulness_engine"] = confidence_truthfulness_engine
    except Exception:
        pass
    current_request_ms = (time.perf_counter() - li_t0) * 1000.0
    _record_hot_path_timing("learning_insights_total_ms", current_request_ms)
    payload["performance_optimization_suite"] = _performance_optimization_snapshot()
    if _learning_budget_exceeded(8.0):
        payload["learning_insights_fast_path"] = True
        payload["learning_insights_fast_path_reason"] = "budget_guard_pre_suite"
        if not isinstance(payload.get("lifecycle_auto_tracking"), dict):
            payload["lifecycle_auto_tracking"] = _lifecycle_tracking_summary_v1(limit=300)
        payload["last_updated_utc"] = _now_utc_iso()
        return payload
    payload.update(_build_hold_measure_status(payload, eval_payload))
    payload = _apply_learning_tab_consistency(payload, eval_payload)
    auto_premium_step = str(os.getenv("ASTRA_PREMIUM_AUTO_STEP_ON_LEARNING", "0")).strip().lower() in {"1", "true", "yes", "on"}
    if auto_premium_step:
        try:
            premium_step = _run_premium_backfill_step_if_due(force=False)
        except Exception as e:
            premium_step = {"ok": False, "reason": f"premium_step_error:{str(e)[:120]}"}
    else:
        premium_step = {"ok": True, "skipped": True, "reason": "auto_step_disabled"}
    payload["premium_phase_learning_status"] = _premium_learning_status_payload()
    payload["premium_backfill_last_step"] = premium_step
    payload["premium_learning_acceleration"] = {
        "fresh_trade_signature_cache_ttl_seconds": int(TRADE_JOURNAL_SIGNATURE_TTL_SECONDS),
        "fresh_outcome_rows_cache_ttl_seconds": int(TRADE_JOURNAL_OUTCOME_ROWS_TTL_SECONDS),
        "learning_insights_ttl_seconds": int(LEARNING_INSIGHTS_TTL_SECONDS),
        "deep_refresh_seconds": int(LEARNING_INSIGHTS_DEEP_REFRESH_SECONDS),
        "outcome_cohort_mode": str((eval_payload or {}).get("cohort_mode") or "unavailable"),
        "post_change_mode": str((eval_payload or {}).get("post_change_cohort_mode") or "unavailable"),
        "post_change_evidence_ready": bool((eval_payload or {}).get("post_change_evidence_ready", False)),
        "post_change_confidence_ready": bool((eval_payload or {}).get("post_change_confidence_ready", False)),
    }
    payload["lifecycle_auto_tracking"] = _lifecycle_tracking_summary_v1(limit=300)
    payload = _ensure_learning_payload_handoff(payload, reason_hint="learning_insights_endpoint_final")
    if not isinstance(payload.get("lifecycle_auto_tracking"), dict):
        payload["lifecycle_auto_tracking"] = _lifecycle_tracking_summary_v1(limit=300)
    payload["last_updated_utc"] = _now_utc_iso()
    return payload


@router.get("/api/learning_weights")
def learning_weights():
    try:
        insights_payload = _normalize_learning_insights_payload(LEARNING_LEDGER.insights())
        payload = _build_learning_weights_payload(insights_payload)
    except Exception as e:
        payload = _default_learning_weights_payload(
            message=f"Learning weights unavailable: {str(e)[:120]}"
        )
    payload["last_updated_utc"] = _now_utc_iso()
    return payload


_schedule_runtime_warmup()
